import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Profesiones en Syrolands","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/overview.md","filePath":"es/guide/professions/overview.md"}'),o={name:"es/guide/professions/overview.md"};function n(s,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="professions-in-syrolands" tabindex="-1">Profesiones en Syrolands <a class="header-anchor" href="#professions-in-syrolands" aria-label="Enlace permanente a &quot;Profesiones en Syrolands&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No se ha establecido que el nuevo diseño sea jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Los oficios forman parte de la aventura, con utilidad en expediciones, exploración y economía.</li><li>Habilidad, técnicas, práctica y reputación crean una identidad profesional.</li><li>El conocimiento y el trabajo interactivo importan más allá de la suma de habilidades; estos sistemas siguen en estado Propuesto.</li></ul><p>Los oficios forman parte de la aventura. Deberían crear decisiones útiles de exploración, supervivencia, mantenimiento y comercio sin convertirse en mejoras genéricas de combate.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concepto</th><th>Qué significa</th></tr></thead><tbody><tr><td>Habilidad</td><td>Capacidad general dentro del presupuesto compartido del personaje</td></tr><tr><td>Técnica</td><td>Conocimiento aprendido, como Distillation o Bowmaking</td></tr><tr><td>Camino profesional</td><td>Habilidad + técnicas + práctica</td></tr><tr><td>Identidad</td><td>Aquello que los demás saben que fabricas bien</td></tr><tr><td>Diario</td><td>Descubrimientos mediante maestros, libros, observación y experimentos</td></tr></tbody></table><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Etapa</th><th>Dirección</th></tr></thead><tbody><tr><td>Conocimiento inicial</td><td>La habilidad baja ya permite trabajo útil</td></tr><tr><td>Práctica</td><td>La habilidad amplía el trabajo posible y su consistencia</td></tr><tr><td>Descubrimiento</td><td>El conocimiento abre opciones; 100 no revela todo</td></tr><tr><td>Maestría</td><td>Técnicas, reputación y comprensión importan más allá de los totales de habilidad</td></tr><tr><td>Producción</td><td>Los procedimientos conocidos pueden permitir lotes en puestos de trabajo que consumen tiempo y materiales</td></tr></tbody></table><p>El límite compartido propuesto es aproximadamente 700 en total / 100 normales por habilidad, no valores definitivos. No hacen falta siete habilidades al máximo para ser viable. Los encargos recompensan resultados útiles; la reputación refleja trabajo real. Los consejos pueden compartirse, pero la ejecución sigue importando.</p><h2 id="explore-the-professions" tabindex="-1">Explora las profesiones <a class="header-anchor" href="#explore-the-professions" aria-label="Enlace permanente a &quot;Explora las profesiones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profesión</th><th>Función</th></tr></thead><tbody><tr><td><a href="/Syrolands-Public/es/guide/professions/cooking.html">Cooking</a></td><td>Alimentación, preparación y supervivencia</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/alchemy.html">Alchemy</a></td><td>Reacciones, preparaciones y apoyo en expediciones</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/mining.html">Mining</a></td><td>Geología, extracción y excavación diseñada</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Blacksmithing</a></td><td>Metalurgia, equipo y mantenimiento</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/tailoring.html">Tailoring</a></td><td>Ajuste, protección flexible y moda</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/lumberjacking.html">Lumberjacking</a></td><td>Selección de madera y tala</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpentry</a></td><td>Trabajo de madera, construcción y Bowmaking aprendido</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/tinkering.html">Tinkering</a></td><td>Mecanismos, seguridad y dispositivos</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/inscription.html">Inscription</a></td><td>Pergaminos, variantes, grimorios y notación</td></tr></tbody></table><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un explorador que conoce Blacksmithing puede contribuir al mantenimiento del equipo sin convertirse en un personaje limitado al taller.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/characters/progression.html">Progresión</a> · <a href="/Syrolands-Public/es/guide/characters/skills.html">Maestros</a> · <a href="/Syrolands-Public/es/guide/characters/techniques.html">Técnicas</a> · <a href="/Syrolands-Public/es/guide/characters/character-creation.html">Orígenes</a> · <a href="/Syrolands-Public/es/guide/items/item-quality.html">Calidad de objetos</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Especificación completa</a></p><p><span id="crafts-belong-to-adventurers"></span><span id="learning-and-becoming-known"></span><span id="knowledge-and-production"></span><span id="shared-character-rules"></span><span id="inscription-and-magical-knowledge"></span></p>',17)])])}const u=a(o,[["render",n]]);export{h as __pageData,u as default};
